	@ParameterizedTest
	@ValueSource(strings = { "filter", "operator" })
	void partialPostCommitFailureSettlesEachReceiptOnceAndPreservesThePrimaryError(
			String failedService, @TempDir Path dataDir)
			throws Exception {
		LmdbStore store = newStore(dataDir);
		store.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbSailStore backing = store.getBackingStore();
			TripleStore triples = backing.getTripleStore();
			LmdbEvaluationStatistics evaluationStatistics = evaluationStatistics(backing);
			LmdbFilterSelectivityStats filterStats = evaluationStatistics.estimatorRuntime().filters();
			LmdbOperatorFeedbackStats operatorStats = evaluationStatistics.estimatorRuntime().feedback();
			assertNotNull(filterStats);
			assertNotNull(operatorStats);
			LeoSurfaceKey learnedKey = seedOperatorEvidence(operatorStats);

			List<Long> filterReceipts = new CopyOnWriteArrayList<>();
			List<Long> operatorReceipts = new CopyOnWriteArrayList<>();
			AtomicInteger filterResets = new AtomicInteger();
			AtomicInteger operatorResets = new AtomicInteger();
			AtomicBoolean failFirstFilterMaintenance = new AtomicBoolean(true);
			AtomicBoolean failFirstOperatorMaintenance = new AtomicBoolean(true);
			AtomicBoolean failFirstOperatorReset = new AtomicBoolean("operator".equals(failedService));
			AssertionError injected = new AssertionError("injected partial learned-state failure from " + failedService);
			AssertionError resetFailure = new AssertionError("injected operator reset failure");
			filterStats.setLearnedStateObserver(new LmdbFilterSelectivityStats.LearnedStateObserver() {
				@Override
				public void storeMutationRecorded(long committedStatementMutationStamp) {
					filterReceipts.add(committedStatementMutationStamp);
					if (failedService.equals("filter") && failFirstFilterMaintenance.compareAndSet(true, false)) {
						throw injected;
					}
				}

				@Override
				public void learnedStateReset() {
					filterResets.incrementAndGet();
				}
			});
			operatorStats.setLearnedStateObserver(new LmdbOperatorFeedbackStats.LearnedStateObserver() {
				@Override
				public void storeMutationRecorded(long committedStatementMutationStamp, Set<Long> predicateIds,
						LmdbOperatorFeedbackStats.MutationExtent extent) {
					operatorReceipts.add(committedStatementMutationStamp);
					if (failedService.equals("operator")
							&& failFirstOperatorMaintenance.compareAndSet(true, false)) {
						throw injected;
					}
				}

				@Override
				public void learnedStateReset() {
					operatorResets.incrementAndGet();
					if (failFirstOperatorReset.compareAndSet(true, false)) {
						throw resetFailure;
					}
				}
			});

			long generationBeforeFirst = triples.getNativeCommitGeneration();
			try (SailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(VF.createIRI("urn:test:post-commit-recovery:first"), PREDICATE,
						VF.createLiteral("first"));
				assertSame(injected, assertThrows(AssertionError.class, connection::commit),
						"post-commit recovery must preserve the original fatal observer error");
			}
			TripleStore.StatementCommitReceipt firstReceipt = triples.statementCommitReceiptAfter(generationBeforeFirst);
			assertNotNull(firstReceipt, "the receipt proves the native data commit completed before the error");

			long generationBeforeSecond = triples.getNativeCommitGeneration();
			assertDoesNotThrow(() -> addStatement(store, "second"), "the same store remains writable after settlement");
			TripleStore.StatementCommitReceipt secondReceipt = triples.statementCommitReceiptAfter(generationBeforeSecond);
			assertNotNull(secondReceipt);

			assertEquals(2L, size(store), "both native commits remain durable despite the first observer error");
			assertEquals(List.of(firstReceipt.sequence(), secondReceipt.sequence()), filterReceipts,
					"completed filter maintenance is not replayed while settling the later service");
			assertEquals(List.of(firstReceipt.sequence(), secondReceipt.sequence()), operatorReceipts,
					"each distinct committed receipt reaches operator maintenance once");
			assertEquals(2, filterResets.get(), "the filter service resets once for each committed receipt");
			assertEquals("operator".equals(failedService) ? 1 : 0, operatorResets.get(),
					"only an operator service with uncertain maintenance is reset");
			if ("operator".equals(failedService)) {
				assertTrue(List.of(injected.getSuppressed()).contains(resetFailure),
						"a failed reset is retained without replacing the primary service error");
				assertTrue(operatorStats.evidence(learnedKey).isEmpty(),
						"the provider whose reset callback failed must not expose its retained evidence");
			}
		} finally {
			store.shutDown();
		}
	}

