	@Test
	void resetObserverFailureLeavesARealPublishedProviderUncleared(@TempDir Path dataDir) throws Exception {
		LmdbStore store = newStore(dataDir);
		store.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbOperatorFeedbackStats operatorStats = evaluationStatistics(store.getBackingStore())
					.estimatorRuntime().feedback();
			LeoSurfaceKey key = seedOperatorEvidence(operatorStats);
			assertTrue(operatorStats.evidence(key).isPresent(), "the real published feedback provider is seeded");
			AssertionError injected = new AssertionError("injected reset observer failure");
			operatorStats.setLearnedStateObserver(new LmdbOperatorFeedbackStats.LearnedStateObserver() {
				@Override
				public void learnedStateReset() {
					throw injected;
				}
			});
			assertSame(injected, assertThrows(AssertionError.class, operatorStats::reset));
			assertTrue(operatorStats.evidence(key).isEmpty(),
					"a failed reset must fail closed instead of exposing evidence it could not clear");
			operatorStats.setLearnedStateObserver(null);
			assertDoesNotThrow(operatorStats::reset, "a later successful reset reconciles the provider");
			LeoSurfaceKey recoveredKey = seedOperatorEvidence(operatorStats);
			assertTrue(operatorStats.evidence(recoveredKey).isPresent(),
					"a successful reset permits new evidence after the provider is reconciled");
		} finally {
			store.shutDown();
		}
	}

